const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
require('dotenv').config();

const app = express();
app.use(cors());
app.use(express.json());

const PORT = process.env.PORT || 5000;
const MONGO_URI = process.env.MONGO_URI;

// Check and connect to Live MongoDB Atlas Cloud
if (!MONGO_URI) {
  console.error("CRITICAL ERROR: MONGO_URI is missing from your .env file!");
} else {
  console.log("Attempting connection to Live MongoDB Atlas...");
}

mongoose.connect(MONGO_URI)
  .then(() => console.log('Successfully connected to Live MongoDB Atlas!'))
  .catch(err => console.error('Database connection error:', err.message));

// Mongoose Listing Schema
const listingSchema = new mongoose.Schema({
  title: String,
  category: String,
  brand: String,
  condition: String,
  age: Number,
  actionType: String,
  estimatedValue: Number,
  imageUrl: String,
  status: { type: String, default: 'Sorted' },
  greenCoins: Number,
  createdAt: { type: Date, default: Date.now }
});

const Listing = mongoose.model('Listing', listingSchema);

// API Routes
app.get('/api/listings', async (req, res) => {
  try {
    const listings = await Listing.find().sort({ createdAt: -1 });
    res.json(listings);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/listings', async (req, res) => {
  try {
    const newListing = new Listing(req.body);
    await newListing.save();
    res.status(201).json(newListing);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.patch('/api/listings/:id/status', async (req, res) => {
  try {
    const { status } = req.body;
    const updated = await Listing.findByIdAndUpdate(req.params.id, { status }, { new: true });
    res.json(updated);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.listen(PORT, () => {
  console.log(`ReCircuit Backend running on port ${PORT}`);
});